    fun encode(msg: WPT_ChargeLoopRes): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(28u, 6)   // document element selector
        encodeWPT_ChargeLoopRes(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

    fun decodeAny(src: ByteArray): Any {
        require(src.isNotEmpty() && src[0] == EXI_HEADER) { "Invalid EXI header." }
        val r = BitReader(src, 1)
        return when (val sel = r.readBits(6)) {
            33u -> decodeWPT_FinePositioningSetupReq(r)
            34u -> decodeWPT_FinePositioningSetupRes(r)
            31u -> decodeWPT_FinePositioningReq(r)
            32u -> decodeWPT_FinePositioningRes(r)
            35u -> decodeWPT_PairingReq(r)
            36u -> decodeWPT_PairingRes(r)
            29u -> decodeWPT_ChargeParameterDiscoveryReq(r)
            30u -> decodeWPT_ChargeParameterDiscoveryRes(r)
            25u -> decodeWPT_AlignmentCheckReq(r)
            26u -> decodeWPT_AlignmentCheckRes(r)
            27u -> decodeWPT_ChargeLoopReq(r)
            28u -> decodeWPT_ChargeLoopRes(r)
            else -> throw IllegalArgumentException("Unknown document index $sel.")
        }
    }

    private fun encodeMessageHeaderType(w: BitWriter, msg: MessageHeaderType) {
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeBinary(w, msg.sessionID)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeUnsignedInteger(w, msg.timeStamp.toULong())
        w.writeBits(0u, 1)   // child EE
        var st0 = 0
        var done0 = false
        while (!done0) {
            when (st0) {
                0 -> {
                    if (msg.signature != null) {
                        w.writeBits(0u, 2)   // Signature
                        encodeSignatureType(w, msg.signature!!)
                        st0 = 1
                    } else {
                        w.writeBits(1u, 2)   // element EE
                        done0 = true
                    }
                }
                1 -> {
                    w.writeBits(0u, 1)   // element EE
                    done0 = true
                }
            }
        }
    }

    private fun decodeMessageHeaderType(r: BitReader): MessageHeaderType {
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _sessionID = ExiPrimitives.readBinary(r)
        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _timeStamp = ExiPrimitives.readUnsignedInteger(r).toULong()
        r.readBits(1)   // child EE
        var _signature: SignatureType? = null
        var st1 = 0
        var done1 = false
        while (!done1) {
            when (st1) {
                0 -> {
                    when (r.readBits(2)) {
                        0u -> {
                            _signature = decodeSignatureType(r)
                            st1 = 1
                        }
                        1u -> done1 = true   // element EE
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                1 -> {
                    when (r.readBits(1)) {
                        0u -> done1 = true   // element EE
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
            }
        }
        return MessageHeaderType(_sessionID, _timeStamp, _signature)
    }

