                                if (lc == 1u) break   // element EE (list end)
                                require(lc == 0u && manufacturerSpecificDataContainerList.size < 16) { "invalid repeating-element event code" }
                                r.readBits(1)   // value-start
                                val manufacturerSpecificDataContainerListNext = ExiPrimitives.readBinary(r)
                                r.readBits(1)   // child EE
                                manufacturerSpecificDataContainerList.add(manufacturerSpecificDataContainerListNext)
                            }
                            done97 = true
                        }
                        2u -> done97 = true   // element EE
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                2 -> {
                    when (r.readBits(2)) {
                        0u -> {   // ManufacturerSpecificDataContainer
                            r.readBits(1)   // value-start
                            val manufacturerSpecificDataContainerListFirst = ExiPrimitives.readBinary(r)
                            r.readBits(1)   // child EE
                            manufacturerSpecificDataContainerList.add(manufacturerSpecificDataContainerListFirst)
                            while (true) {
                                val lc = r.readBits(2)
                                if (lc == 1u) break   // element EE (list end)
                                require(lc == 0u && manufacturerSpecificDataContainerList.size < 16) { "invalid repeating-element event code" }
                                r.readBits(1)   // value-start
                                val manufacturerSpecificDataContainerListNext = ExiPrimitives.readBinary(r)
                                r.readBits(1)   // child EE
                                manufacturerSpecificDataContainerList.add(manufacturerSpecificDataContainerListNext)
                            }
                            done97 = true
                        }
                        1u -> done97 = true   // element EE
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                3 -> {
                    when (r.readBits(1)) {
                        0u -> done97 = true   // element EE
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
            }
        }
        return WPT_ChargeLoopRes(_header, _responseCode, _eVSEStatus, _meterInfo, _receipt, _eVPCPowerRequest!!, _sDPowerInput, _sPCMaxOutputPowerLimit!!, _sPCMinOutputPowerLimit, _sPCChargeDiagnostics, _sPCOperatingFrequency, _sPCPowerControlParameter, manufacturerSpecificDataContainerList)
    }

}
